mapper.select:
SELECT b.* FROM ( SELECT a.*, ROWNUM AS rnum FROM ( SELECT p.hotdeal_id AS seq, p.hotdeal_title AS subject, p.user_id AS id, p.hotdeal_view_count AS readcount, TO_CHAR(p.hotdeal_regdate, 'YYYY-MM-DD HH24:MI:SS') AS regdate, u.nickname AS name, s.hotdeal_status AS status, (SELECT MIN(hotdeal_image_url) FROM tblHotDealImage WHERE hotdeal_id = p.hotdeal_id AND ROWNUM = 1) AS img FROM tblHotDealPost p LEFT JOIN tblUser u ON p.user_id = u.user_id LEFT JOIN tblHotDealStatus s ON p.hotdeal_status_id = s.hotdeal_status_id
WHERE ${column} LIKE '%' || #{word} || '%'
ORDER BY p.hotdeal_id DESC ) a ) b WHERE rnum BETWEEN #{begin} AND #{end}

mapper.update:
UPDATE tblHotDealPost
SET hotdeal_view_count = hotdeal_view_count + 1
WHERE hotdeal_id = #{seq}

UPDATE tblHotDealComment 
SET hotdeal_comment_content = #{content} 
WHERE hotdeal_comment_id = #{seq} AND user_id = #{useq}
